CREATE TABLE finance_scheduled_transaction (id UUID PRIMARY KEY DEFAULT uuid_v7(),ledger_id UUID NOT NULL,owner_id UUID NOT NULL,rule VARCHAR(256) NOT NULL,next_run TIMESTAMPTZ NOT NULL,type VARCHAR(24) NOT NULL,account_id UUID NOT NULL,target_account_id UUID,amount NUMERIC(19,4) NOT NULL,currency CHAR(3) NOT NULL,category_id UUID,payee VARCHAR(256),note TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(amount>0),CHECK(type IN ('INCOME','EXPENSE','TRANSFER','ADJUSTMENT')),FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id),FOREIGN KEY(account_id) REFERENCES finance_account(id),FOREIGN KEY(target_account_id) REFERENCES finance_account(id)); CREATE INDEX idx_finance_scheduled_due ON finance_scheduled_transaction(active,next_run);
